    event.preventDefault();
  }, { passive: false });
  ```

- Если вы хотите **сохранить прокрутку страницы**, но **изменить позицию камеры**, используйте:
  ```javascript
  window.addEventListener('wheel', (event) => {
    cameraZ += event.deltaY * 0.005;
    camera.position.z = cameraZ;
  }, { passive: false });
  ```

---

